import os
import sys
import xml.etree.ElementTree as ET

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    xml_path = sys.argv[1]
    output_dir = sys.argv[2]

    tree = ET.parse(xml_path)
    root = tree.getroot()

    assets = {}
    for asset_elem in root.findall('asset'):
        name = asset_elem.get('name')
        if name:
            assets[name] = asset_elem.text.strip()

    while True:
        try:
            line = sys.stdin.readline().strip()
        except EOFError:
            break

        if not line:
            continue

        if line in assets:
            source_path = assets[line]
            dest_path = os.path.join(output_dir, source_path)
            os.makedirs(os.path.dirname(dest_path), exist_ok=True)
            os.replace(os.path.join(xml_path, source_path), dest_path)
            print(dest_path)
        else:
            print(f"MISSING {line}")

if __name__ == "__main__":
    main()
